// @FIGURE_CODE_BEGIN
// x-axis → Line + ConeGeometry arrowhead, black, positive math x direction
// y-axis → Line + ConeGeometry arrowhead, black, positive math y direction
// z-axis → Line + ConeGeometry arrowhead, black, vertical positive math z direction
// origin → small SphereGeometry, black
// construction rays → dashed Line objects from origin to spherical-cell corners
// meridian shell arcs → dashed Line arcs at rho and rho+Delta rho
// horizontal theta arcs → dashed Line arcs in xy-plane
// angle markers → black curved Line arcs for Delta phi and Delta theta
// Delta rho bracket → black LineSegments with tick marks beside z-axis
// spherical subbox faces → six sampled transparent orange BufferGeometry surface patches
// spherical subbox outlines → dark-orange Line curves along all twelve curved edges
// highlighted cell edges → colored TubeGeometry paths for Delta rho, rho Delta phi, rho sin phi Delta theta
// blue footprint → translucent annular-sector Mesh plus dark-blue outline Line curves
// projection droplines → dashed vertical Line objects from cell corners to xy-plane
// rho sin phi bracket → black dimension line with small ticks in xy-plane
// footprint leader arrow → black Line + ConeGeometry pointing to blue azimuth edge
// sweep arrow → thick pale-gray TubeGeometry Bezier curve plus ConeGeometry arrowhead
// enlarged inset faces → translucent orange affine/tangent hexahedron Mesh faces
// enlarged inset outlines → dark-orange LineSegments around hexahedron
// highlighted inset edges → colored TubeGeometry edges matching the three factors
// inset leader arrows → black Line + ConeGeometry arrows from labels to inset edges
// formula → CSS label below inset, exactly Delta V = rho^2 sin phi Delta rho Delta phi Delta theta

const rho0 = 2.15;
const phi0 = 0.90;
const theta0 = 0.62;
const AXIS_LEN = 3.5;
const ORANGE = 0xf7944d;
const ORANGE_EDGE = 0xf05a24;
const BLUE = 0x3b6fb6;
const BLUE_EDGE = 0x173f7a;
const GREY = 0x555555;
const RED = 0xe53935;
const PURPLE = 0x7b1fa2;
const EDGE_BLUE = 0x1565c0;

function M(x, y, z) {
  return new THREE.Vector3(y, z, x);
}

function sph(rho, phi, theta) {
  const s = Math.sin(phi);
  return M(rho * s * Math.cos(theta), rho * s * Math.sin(theta), rho * Math.cos(phi));
}

function vFromMath(v) {
  return M(v.x, v.y, v.z);
}

function mathBasis(phi, theta) {
  return {
    er: vFromMath(new THREE.Vector3(Math.sin(phi) * Math.cos(theta), Math.sin(phi) * Math.sin(theta), Math.cos(phi))).normalize(),
    ep: vFromMath(new THREE.Vector3(Math.cos(phi) * Math.cos(theta), Math.cos(phi) * Math.sin(theta), -Math.sin(phi))).normalize(),
    et: vFromMath(new THREE.Vector3(-Math.sin(theta), Math.cos(theta), 0)).normalize()
  };
}

function lineObj(points, color = 0x000000, dashed = false, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.08, gapSize: 0.055, transparent: opacity < 1, opacity })
    : new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const l = new THREE.Line(geom, mat);
  if (dashed) l.computeLineDistances();
  return l;
}

function lineSegmentsObj(points, color = 0x000000) {
  return new THREE.LineSegments(
    new THREE.BufferGeometry().setFromPoints(points),
    new THREE.LineBasicMaterial({ color })
  );
}

function addConeArrow(end, dir, color = 0x000000, radius = 0.055, height = 0.18) {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(radius, height, 24), new THREE.MeshBasicMaterial({ color }));
  const dvec = dir.clone().normalize();
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dvec);
  cone.position.copy(end).addScaledVector(dvec, -height / 2);
  return cone;
}

function addArrowLine(group, start, end, color = 0x000000, radius = 0.045, height = 0.16) {
  group.add(lineObj([start, end], color));
  group.add(addConeArrow(end, end.clone().sub(start), color, radius, height));
}

function clearGroup(group) {
  while (group.children.length) {
    const o = group.children.pop();
    o.traverse?.(c => {
      c.geometry?.dispose?.();
      if (Array.isArray(c.material)) c.material.forEach(m => m.dispose?.());
      else c.material?.dispose?.();
    });
  }
}

function curvePts(fn, n = 40) {
  const pts = [];
  for (let i = 0; i < n; i++) pts.push(fn(i / (n - 1)));
  return pts;
}

function updateTube(mesh, pts, radius = 0.026) {
  const old = mesh.geometry;
  const curve = new THREE.CatmullRomCurve3(pts);
  mesh.geometry = new THREE.TubeGeometry(curve, Math.max(8, pts.length * 2), radius, 10, false);
  old?.dispose?.();
}

function patchMesh(fixed, value, dr, dp, dt) {
  const seg = 8;
  const verts = [];
  const idx = [];
  for (let i = 0; i <= seg; i++) {
    for (let j = 0; j <= seg; j++) {
      const u = i / seg, v = j / seg;
      let r, p, t;
      if (fixed === 'rho') { r = value; p = phi0 + dp * u; t = theta0 + dt * v; }
      if (fixed === 'phi') { r = rho0 + dr * u; p = value; t = theta0 + dt * v; }
      if (fixed === 'theta') { r = rho0 + dr * u; p = phi0 + dp * v; t = value; }
      const q = sph(r, p, t);
      verts.push(q.x, q.y, q.z);
    }
  }
  for (let i = 0; i < seg; i++) {
    for (let j = 0; j < seg; j++) {
      const a = i * (seg + 1) + j, b = a + 1, c = a + (seg + 1), d2 = c + 1;
      idx.push(a, c, b, b, c, d2);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(idx);
  geom.computeVertexNormals();
  const mat = new THREE.MeshBasicMaterial({
    color: ORANGE,
    transparent: true,
    opacity: 0.35,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.renderOrder = 5;
  return mesh;
}

function faceMeshFromCorners(corners, faces, color, opacity) {
  const verts = [];
  const idx = [];
  for (const v of corners) verts.push(v.x, v.y, v.z);
  for (const f of faces) idx.push(f[0], f[1], f[2], f[0], f[2], f[3]);
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(idx);
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: false
  }));
  mesh.renderOrder = 6;
  return mesh;
}

const staticGroup = new THREE.Group();
const dynamicGroup = new THREE.Group();
const highlightGroup = new THREE.Group();
const insetLeaderGroup = new THREE.Group();
scene.add(staticGroup, dynamicGroup, highlightGroup, insetLeaderGroup);

addArrowLine(staticGroup, new THREE.Vector3(0, 0, 0), M(AXIS_LEN, 0, 0), 0x000000, 0.055, 0.20);
addArrowLine(staticGroup, new THREE.Vector3(0, 0, 0), M(0, AXIS_LEN, 0), 0x000000, 0.055, 0.20);
addArrowLine(staticGroup, new THREE.Vector3(0, 0, 0), M(0, 0, AXIS_LEN), 0x000000, 0.055, 0.20);
staticGroup.add(new THREE.Mesh(new THREE.SphereGeometry(0.045, 16, 12), new THREE.MeshBasicMaterial({ color: 0x000000 })));

const hCellR = new THREE.Mesh(new THREE.BufferGeometry(), new THREE.MeshBasicMaterial({ color: RED }));
const hCellP = new THREE.Mesh(new THREE.BufferGeometry(), new THREE.MeshBasicMaterial({ color: PURPLE }));
const hCellT = new THREE.Mesh(new THREE.BufferGeometry(), new THREE.MeshBasicMaterial({ color: EDGE_BLUE }));
const hInsetR = new THREE.Mesh(new THREE.BufferGeometry(), new THREE.MeshBasicMaterial({ color: RED }));
const hInsetP = new THREE.Mesh(new THREE.BufferGeometry(), new THREE.MeshBasicMaterial({ color: PURPLE }));
const hInsetT = new THREE.Mesh(new THREE.BufferGeometry(), new THREE.MeshBasicMaterial({ color: EDGE_BLUE }));
highlightGroup.add(hCellR, hCellP, hCellT, hInsetR, hInsetP, hInsetT);

registerInteractive(hCellR, { title: 'Radial edge Δρ', tooltip: 'Δρ', body: 'Changing ρ moves directly outward from the origin, so this edge has length Δρ.' });
registerInteractive(hInsetR, { title: 'Radial edge Δρ', tooltip: 'Δρ', body: 'This red-orange inset edge is the radial thickness Δρ.' });
registerInteractive(hCellP, { title: 'Polar arc ρ Δφ', tooltip: 'ρ Δφ', body: 'Changing polar angle φ sweeps an arc whose length is approximately ρ Δφ.' });
registerInteractive(hInsetP, { title: 'Polar edge ρ Δφ', tooltip: 'ρ Δφ', body: 'This purple inset edge represents the meridian arc length ρ Δφ.' });
registerInteractive(hCellT, { title: 'Azimuthal arc ρ sinφ Δθ', tooltip: 'ρ sinφ Δθ', body: 'Changing θ sweeps around a horizontal circle of radius ρ sinφ.' });
registerInteractive(hInsetT, { title: 'Azimuthal edge ρ sinφ Δθ', tooltip: 'ρ sinφ Δθ', body: 'This blue edge is the horizontal circular arc length ρ sinφ Δθ.' });

let activeKey = null;
let coordLabels = [];
let insetLabels = [];
let formulaLabel = null;
let labelRefs = {};

function addEdgeCurve(group, pts, color = ORANGE_EDGE, dashed = false) {
  const l = lineObj(pts, color, dashed);
  group.add(l);
  return l;
}

function buildSweepArrow(dr, dp, dt) {
  const start = sph(rho0 + dr, phi0 + dp * 0.15, theta0 + dt).add(new THREE.Vector3(0.25, 0.45, 0.05));
  const end = new THREE.Vector3(3.45, 2.25, 0.35);
  const mid = new THREE.Vector3(1.75, 3.25, 0.1);
  const curve = new THREE.QuadraticBezierCurve3(start, mid, end);
  const pts = curve.getPoints(46);
  const tube = new THREE.Mesh(
    new THREE.TubeGeometry(curve, 46, 0.07, 14, false),
    new THREE.MeshBasicMaterial({ color: 0xb8b8b8, transparent: true, opacity: 0.82 })
  );
  const outline = new THREE.Mesh(
    new THREE.TubeGeometry(curve, 46, 0.086, 14, false),
    new THREE.MeshBasicMaterial({ color: 0x999999, transparent: true, opacity: 0.28 })
  );
  dynamicGroup.add(outline, tube);
  const tan = pts[pts.length - 1].clone().sub(pts[pts.length - 3]).normalize();
  dynamicGroup.add(addConeArrow(end, tan, 0xb8b8b8, 0.18, 0.38));
}

function insetCorners(dr, dp, dt) {
  const pm = phi0 + dp / 2;
  const tm = theta0 + dt / 2;
  const rm = rho0 + dr / 2;
  const b = mathBasis(pm, tm);
  const S = 2.3;
  const a = dr * S;
  const p = rm * dp * S;
  const t = rm * Math.sin(pm) * dt * S;
  const c = new THREE.Vector3(4.65, 1.45, 0.15);
  const corners = [];
  for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) for (let k = 0; k < 2; k++) {
    corners.push(c.clone()
      .addScaledVector(b.er, (i - 0.5) * a)
      .addScaledVector(b.ep, (j - 0.5) * p)
      .addScaledVector(b.et, (k - 0.5) * t));
  }
  return { corners, dims: { a, p, t }, basis: b, center: c };
}

function cidx(i, j, k) { return i * 4 + j * 2 + k; }

function setEdgeEmphasis() {
  const map = { rho: [hCellR, hInsetR], phi: [hCellP, hInsetP], theta: [hCellT, hInsetT] };
  for (const key of Object.keys(map)) {
    for (const m of map[key]) {
      const on = !activeKey || activeKey === key;
      m.material.opacity = on ? 1 : 0.32;
      m.material.transparent = true;
    }
  }
}

function updateLabelsVisibility() {
  const mode = document.getElementById('labelOverlay').value;
  for (const e of coordLabels) e.div.style.visibility = mode === 'Coordinate diagram labels' ? 'visible' : 'hidden';
  for (const e of insetLabels) e.div.style.visibility = mode === 'Enlarged element labels' ? 'visible' : 'hidden';
  if (formulaLabel) formulaLabel.div.style.visibility = 'visible';
  insetLeaderGroup.visible = mode === 'Enlarged element labels';
}

function updateFigure() {
  clearGroup(dynamicGroup);
  clearGroup(insetLeaderGroup);
  const dr = parseFloat(document.getElementById('deltaRho').value);
  const dp = parseFloat(document.getElementById('deltaPhi').value);
  const dt = parseFloat(document.getElementById('deltaTheta').value);
  document.getElementById('deltaRhoVal').textContent = dr.toFixed(2);
  document.getElementById('deltaPhiVal').textContent = dp.toFixed(2);
  document.getElementById('deltaThetaVal').textContent = dt.toFixed(2);

  const r1 = rho0 + dr, p1 = phi0 + dp, t1 = theta0 + dt;
  dynamicGroup.add(patchMesh('rho', rho0, dr, dp, dt), patchMesh('rho', r1, dr, dp, dt));
  dynamicGroup.add(patchMesh('phi', phi0, dr, dp, dt), patchMesh('phi', p1, dr, dp, dt));
  dynamicGroup.add(patchMesh('theta', theta0, dr, dp, dt), patchMesh('theta', t1, dr, dp, dt));

  for (const p of [phi0, p1]) for (const t of [theta0, t1]) {
    addEdgeCurve(dynamicGroup, curvePts(u => sph(rho0 + dr * u, p, t), 18), ORANGE_EDGE);
  }
  for (const r of [rho0, r1]) for (const t of [theta0, t1]) {
    addEdgeCurve(dynamicGroup, curvePts(u => sph(r, phi0 + dp * u, t), 24), ORANGE_EDGE);
  }
  for (const r of [rho0, r1]) for (const p of [phi0, p1]) {
    addEdgeCurve(dynamicGroup, curvePts(u => sph(r, p, theta0 + dt * u), 24), ORANGE_EDGE);
  }

  const cellCorners = [];
  for (const r of [rho0, r1]) for (const p of [phi0, p1]) for (const t of [theta0, t1]) cellCorners.push(sph(r, p, t));
  for (const q of cellCorners) dynamicGroup.add(lineObj([new THREE.Vector3(0, 0, 0), q], GREY, true, 0.75));

  for (const r of [rho0, r1]) {
    for (const th of [theta0, t1]) {
      dynamicGroup.add(lineObj(curvePts(u => sph(r, 0.15 + (p1 + 0.28 - 0.15) * u, th), 56), GREY, true, 0.85));
    }
  }
  const rr0 = rho0 * Math.sin(phi0), rr1 = r1 * Math.sin(p1);
  for (const rad of [rr0, rr1]) {
    dynamicGroup.add(lineObj(curvePts(u => M(rad * Math.cos(theta0 - 0.05 + (dt + 0.22) * u), rad * Math.sin(theta0 - 0.05 + (dt + 0.22) * u), 0), 42), GREY, true, 0.8));
  }

  dynamicGroup.add(lineObj(curvePts(u => sph(0.63, phi0 * 0.72 + dp * u, theta0), 22), 0x000000));
  dynamicGroup.add(lineObj(curvePts(u => M(0.62 * Math.cos(theta0 * u), 0.62 * Math.sin(theta0 * u), 0), 22), 0x000000));

  const z0 = rho0 * Math.cos(phi0);
  const z2 = r1 * Math.cos(phi0);
  const bx = -0.30;
  const bracketPts = [
    M(bx, 0, z0), M(bx, 0, z2),
    M(bx - 0.10, 0, z0), M(bx + 0.10, 0, z0),
    M(bx - 0.10, 0, z2), M(bx + 0.10, 0, z2)
  ];
  dynamicGroup.add(lineSegmentsObj(bracketPts, 0x000000));

  const projVerts = [];
  const projIdx = [];
  const rings = 2, seg = 18;
  for (let i = 0; i <= rings; i++) {
    const rad = rr0 + (rr1 - rr0) * i / rings;
    for (let j = 0; j <= seg; j++) {
      const th = theta0 + dt * j / seg;
      const q = M(rad * Math.cos(th), rad * Math.sin(th), 0);
      projVerts.push(q.x, q.y, q.z);
    }
  }
  for (let i = 0; i < rings; i++) for (let j = 0; j < seg; j++) {
    const a = i * (seg + 1) + j, b = a + 1, c = a + seg + 1, d3 = c + 1;
    projIdx.push(a, c, b, b, c, d3);
  }
  const pg = new THREE.BufferGeometry();
  pg.setAttribute('position', new THREE.Float32BufferAttribute(projVerts, 3));
  pg.setIndex(projIdx);
  const pm = new THREE.Mesh(pg, new THREE.MeshBasicMaterial({ color: BLUE, transparent: true, opacity: 0.45, side: THREE.DoubleSide, depthWrite: false }));
  pm.renderOrder = 3;
  dynamicGroup.add(pm);
  for (const rad of [rr0, rr1]) addEdgeCurve(dynamicGroup, curvePts(u => M(rad * Math.cos(theta0 + dt * u), rad * Math.sin(theta0 + dt * u), 0), 25), BLUE_EDGE);
  for (const th of [theta0, t1]) addEdgeCurve(dynamicGroup, [M(rr0 * Math.cos(th), rr0 * Math.sin(th), 0), M(rr1 * Math.cos(th), rr1 * Math.sin(th), 0)], BLUE_EDGE);

  for (const r of [rho0, r1]) for (const p of [phi0, p1]) for (const t of [theta0, t1]) {
    const top = sph(r, p, t);
    const rad = r * Math.sin(p);
    const bot = M(rad * Math.cos(t), rad * Math.sin(t), 0);
    dynamicGroup.add(lineObj([top, bot], GREY, true, 0.65));
