}

function lineObj(points, color = 0x000000, dashed = false, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = dashed
    ? new THREE.LineDashedMaterial({ color, dashSize: 0.095, gapSize: 0.055, transparent: opacity < 1, opacity })
    : new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const l = new THREE.Line(geom, mat);
  if (dashed) l.computeLineDistances();
  return l;
}

function lineSegmentsObj(points, color = 0x000000) {
  return new THREE.LineSegments(
    new THREE.BufferGeometry().setFromPoints(points),
    new THREE.LineBasicMaterial({ color })
  );
}

function addConeArrow(end, dir, color = 0x000000, radius = 0.055, height = 0.18) {
  const cone = new THREE.Mesh(new THREE.ConeGeometry(radius, height, 24), new THREE.MeshBasicMaterial({ color }));
  const dvec = dir.clone().normalize();
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dvec);
  cone.position.copy(end).addScaledVector(dvec, -height / 2);
  return cone;
}

function addArrowLine(group, start, end, color = 0x000000, radius = 0.045, height = 0.16) {
  group.add(lineObj([start, end], color));
  group.add(addConeArrow(end, end.clone().sub(start), color, radius, height));
}

function clearGroup(group) {
  while (group.children.length) {
    const o = group.children.pop();
    o.traverse?.(c => {
      c.geometry?.dispose?.();
      if (Array.isArray(c.material)) c.material.forEach(m => m.dispose?.());
      else c.material?.dispose?.();
    });
  }
}

function curvePts(fn, n = 40) {
  const pts = [];
  for (let i = 0; i < n; i++) pts.push(fn(i / (n - 1)));
  return pts;
}

function updateTube(mesh, pts, radius = 0.026) {
  const old = mesh.geometry;
  const curve = new THREE.CatmullRomCurve3(pts);
  mesh.geometry = new THREE.TubeGeometry(curve, Math.max(10, pts.length * 3), radius, 12, false);
  old?.dispose?.();
}

function patchMesh(fixed, value, dr, dp, dt) {
  const seg = 8;
  const verts = [];
  const idx = [];
  for (let i = 0; i <= seg; i++) {
    for (let j = 0; j <= seg; j++) {
      const u = i / seg, v = j / seg;
      let r, p, t;
      if (fixed === 'rho') { r = value; p = phi0 + dp * u; t = theta0 + dt * v; }
      if (fixed === 'phi') { r = rho0 + dr * u; p = value; t = theta0 + dt * v; }
      if (fixed === 'theta') { r = rho0 + dr * u; p = phi0 + dp * v; t = value; }
      const q = sph(r, p, t);
      verts.push(q.x, q.y, q.z);
    }
  }
  for (let i = 0; i < seg; i++) {
    for (let j = 0; j < seg; j++) {
      const a = i * (seg + 1) + j, b = a + 1, c = a + (seg + 1), d2 = c + 1;
      idx.push(a, c, b, b, c, d2);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(idx);
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
    color: ORANGE,
    transparent: true,
    opacity: 0.35,
    side: THREE.DoubleSide,
    depthWrite: false
  }));
  mesh.renderOrder = 5;
  return mesh;
}

function faceMeshFromCorners(corners, faces, color, opacity) {
  const verts = [];
  const idx = [];
  for (const v of corners) verts.push(v.x, v.y, v.z);
  for (const f of faces) idx.push(f[0], f[1], f[2], f[0], f[2], f[3]);
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  geom.setIndex(idx);
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: false
  }));
  mesh.renderOrder = 6;
  return mesh;
}

const staticGroup = new THREE.Group();
const dynamicGroup = new THREE.Group();
const highlightGroup = new THREE.Group();
const insetLeaderGroup = new THREE.Group();
scene.add(staticGroup, dynamicGroup, highlightGroup, insetLeaderGroup);

addArrowLine(staticGroup, new THREE.Vector3(0, 0, 0), M(AXIS_LEN, 0, 0), 0x000000, 0.055, 0.20);
addArrowLine(staticGroup, new THREE.Vector3(0, 0, 0), M(0, AXIS_LEN, 0), 0x000000, 0.055, 0.20);
addArrowLine(staticGroup, new THREE.Vector3(0, 0, 0), M(0, 0, AXIS_LEN), 0x000000, 0.055, 0.20);
staticGroup.add(new THREE.Mesh(new THREE.SphereGeometry(0.045, 16, 12), new THREE.MeshBasicMaterial({ color: 0x000000 })));

const edgeMat = new THREE.MeshBasicMaterial({ color: ORANGE_EDGE, transparent: true, opacity: 1 });
const hCellR = new THREE.Mesh(new THREE.BufferGeometry(), edgeMat.clone());
const hCellP = new THREE.Mesh(new THREE.BufferGeometry(), edgeMat.clone());
const hCellT = new THREE.Mesh(new THREE.BufferGeometry(), edgeMat.clone());
const hInsetR = new THREE.Mesh(new THREE.BufferGeometry(), edgeMat.clone());
const hInsetP = new THREE.Mesh(new THREE.BufferGeometry(), edgeMat.clone());
const hInsetT = new THREE.Mesh(new THREE.BufferGeometry(), edgeMat.clone());
highlightGroup.add(hCellR, hCellP, hCellT, hInsetR, hInsetP, hInsetT);

registerInteractive(hCellR, { title: 'Radial edge Δρ', tooltip: 'Δρ', body: 'Changing ρ moves directly outward from the origin, so this edge has length Δρ.' });
registerInteractive(hInsetR, { title: 'Radial edge Δρ', tooltip: 'Δρ', body: 'This inset edge is the radial thickness Δρ.' });
registerInteractive(hCellP, { title: 'Polar arc ρ Δφ', tooltip: 'ρ Δφ', body: 'Changing polar angle φ sweeps an arc whose length is approximately ρ Δφ.' });
registerInteractive(hInsetP, { title: 'Polar edge ρ Δφ', tooltip: 'ρ Δφ', body: 'This inset edge represents the meridian arc length ρ Δφ.' });
registerInteractive(hCellT, { title: 'Azimuthal arc ρ sin φ Δθ', tooltip: 'ρ sin φ Δθ', body: 'Changing θ sweeps around a horizontal circle of radius ρ sin φ.' });
registerInteractive(hInsetT, { title: 'Azimuthal edge ρ sin φ Δθ', tooltip: 'ρ sin φ Δθ', body: 'This inset edge is the horizontal circular arc length ρ sin φ Δθ.' });

let activeKey = null;
let coordLabels = [];
let insetLabels = [];
let formulaLabel = null;
let labelRefs = {};

function addEdgeCurve(group, pts, color = ORANGE_EDGE, dashed = false) {
  const l = lineObj(pts, color, dashed);
  group.add(l);
  return l;
}

function buildSweepArrow(dr, dp, dt) {
  const start = sph(rho0 + dr, phi0 + dp * 0.2, theta0 + dt).add(new THREE.Vector3(0.18, 0.52, 0.04));
  const end = new THREE.Vector3(3.85, 2.05, 0.18);
  const mid = new THREE.Vector3(2.00, 3.25, -0.18);
  const curve = new THREE.QuadraticBezierCurve3(start, mid, end);
  const pts = curve.getPoints(52);
  const outline = new THREE.Mesh(
    new THREE.TubeGeometry(curve, 52, 0.105, 18, false),
    new THREE.MeshBasicMaterial({ color: 0x999999, transparent: true, opacity: 0.34 })
  );
  const tube = new THREE.Mesh(
    new THREE.TubeGeometry(curve, 52, 0.078, 18, false),
    new THREE.MeshBasicMaterial({ color: 0xb8b8b8, transparent: true, opacity: 0.82 })
  );
  dynamicGroup.add(outline, tube);
  const tan = pts[pts.length - 1].clone().sub(pts[pts.length - 4]).normalize();
  dynamicGroup.add(addConeArrow(end, tan, 0xb8b8b8, 0.20, 0.40));
}

function insetCorners(dr, dp, dt) {
  const pm = phi0 + dp / 2;
  const rm = rho0 + dr / 2;
  const S = 2.35;
  const a = dr * S;
  const p = rm * dp * S;
  const t = rm * Math.sin(pm) * dt * S;
  const c = new THREE.Vector3(4.25, 1.47, 0.05);
  const er = new THREE.Vector3(-0.78, 0.12, 0.34).normalize();
  const ep = new THREE.Vector3(0.08, 0.96, -0.14).normalize();
  const et = new THREE.Vector3(0.96, 0.24, -0.34).normalize();
  const corners = [];
  for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) for (let k = 0; k < 2; k++) {
    corners.push(c.clone()
      .addScaledVector(er, (i - 0.5) * a)
      .addScaledVector(ep, (j - 0.5) * p)
      .addScaledVector(et, (k - 0.5) * t));
  }
  return { corners, dims: { a, p, t }, basis: { er, ep, et }, center: c };
}

function cidx(i, j, k) { return i * 4 + j * 2 + k; }

function setEdgeEmphasis() {
  const specs = {
    rho: { meshes: [hCellR, hInsetR], color: RED },
    phi: { meshes: [hCellP, hInsetP], color: PURPLE },
    theta: { meshes: [hCellT, hInsetT], color: EDGE_BLUE }
  };
  for (const key of Object.keys(specs)) {
    for (const m of specs[key].meshes) {
      const on = activeKey === key;
      m.material.color.setHex(on ? specs[key].color : ORANGE_EDGE);
      m.material.opacity = activeKey ? (on ? 1 : 0.34) : 0.95;
      m.material.transparent = true;
    }
  }
}

function updateLabelsVisibility() {
  const mode = document.getElementById('labelOverlay').value;
  const showCoord = mode === 'Both label sets' || mode === 'Coordinate diagram labels';
  const showInset = mode === 'Both label sets' || mode === 'Enlarged element labels';
  for (const e of coordLabels) e.div.style.visibility = showCoord ? 'visible' : 'hidden';
  for (const e of insetLabels) e.div.style.visibility = showInset ? 'visible' : 'hidden';
  if (formulaLabel) formulaLabel.div.style.visibility = showInset ? 'visible' : 'hidden';
  insetLeaderGroup.visible = showInset;
}

function updateFigure() {
  clearGroup(dynamicGroup);
  clearGroup(insetLeaderGroup);
  const dr = parseFloat(document.getElementById('deltaRho').value);
  const dp = parseFloat(document.getElementById('deltaPhi').value);
  const dt = parseFloat(document.getElementById('deltaTheta').value);
  document.getElementById('deltaRhoVal').textContent = dr.toFixed(2);
  document.getElementById('deltaPhiVal').textContent = dp.toFixed(2);
  document.getElementById('deltaThetaVal').textContent = dt.toFixed(2);

  const r1 = rho0 + dr, p1 = phi0 + dp, t1 = theta0 + dt;

  dynamicGroup.add(patchMesh('rho', rho0, dr, dp, dt), patchMesh('rho', r1, dr, dp, dt));
  dynamicGroup.add(patchMesh('phi', phi0, dr, dp, dt), patchMesh('phi', p1, dr, dp, dt));
  dynamicGroup.add(patchMesh('theta', theta0, dr, dp, dt), patchMesh('theta', t1, dr, dp, dt));

  for (const p of [phi0, p1]) for (const t of [theta0, t1]) {
    addEdgeCurve(dynamicGroup, curvePts(u => sph(rho0 + dr * u, p, t), 20), ORANGE_EDGE);
  }
  for (const r of [rho0, r1]) for (const t of [theta0, t1]) {
    addEdgeCurve(dynamicGroup, curvePts(u => sph(r, phi0 + dp * u, t), 30), ORANGE_EDGE);
  }
  for (const r of [rho0, r1]) for (const p of [phi0, p1]) {
    addEdgeCurve(dynamicGroup, curvePts(u => sph(r, p, theta0 + dt * u), 30), ORANGE_EDGE);
  }

  const cellCorners = [];
  for (const r of [rho0, r1]) for (const p of [phi0, p1]) for (const t of [theta0, t1]) cellCorners.push(sph(r, p, t));
  for (const q of cellCorners) dynamicGroup.add(lineObj([new THREE.Vector3(0, 0, 0), q], GREY, true, 0.75));

  for (const r of [rho0, r1]) {
    for (const th of [theta0, t1]) {
      dynamicGroup.add(lineObj(curvePts(u => sph(r, 0.12 + (p1 + 0.42 - 0.12) * u, th), 74), GREY, true, 0.88));
    }
    const thMid = theta0 + dt / 2;
    dynamicGroup.add(lineObj(curvePts(u => sph(r, 0.16 + (p1 + 0.35 - 0.16) * u, thMid), 68), GREY, true, 0.52));
  }

  const rr0 = rho0 * Math.sin(phi0), rr1 = r1 * Math.sin(p1);
  for (const rad of [rr0, rr1]) {
    dynamicGroup.add(lineObj(curvePts(u => M(rad * Math.cos(theta0 - 0.12 + (dt + 0.36) * u), rad * Math.sin(theta0 - 0.12 + (dt + 0.36) * u), 0), 48), GREY, true, 0.8));
  }

  dynamicGroup.add(lineObj(curvePts(u => sph(0.64, phi0 * 0.70 + dp * u, theta0), 24), 0x000000));
  dynamicGroup.add(lineObj(curvePts(u => M(0.62 * Math.cos(theta0 * u), 0.62 * Math.sin(theta0 * u), 0), 24), 0x000000));

  const z0 = rho0 * Math.cos(phi0);
  const z2 = r1 * Math.cos(phi0);
  const bx = -0.31;
  dynamicGroup.add(lineSegmentsObj([
    M(bx, 0, z0), M(bx, 0, z2),
    M(bx - 0.10, 0, z0), M(bx + 0.10, 0, z0),
    M(bx - 0.10, 0, z2), M(bx + 0.10, 0, z2)
  ], 0x000000));

  const projVerts = [];
  const projIdx = [];
  const rings = 2, seg = 20;
  for (let i = 0; i <= rings; i++) {
    const rad = rr0 + (rr1 - rr0) * i / rings;
    for (let j = 0; j <= seg; j++) {
      const th = theta0 + dt * j / seg;
      const q = M(rad * Math.cos(th), rad * Math.sin(th), 0);
      projVerts.push(q.x, q.y, q.z);
    }
  }
  for (let i = 0; i < rings; i++) for (let j = 0; j < seg; j++) {
    const a = i * (seg + 1) + j, b = a + 1, c = a + seg + 1, d3 = c + 1;
    projIdx.push(a, c, b, b, c, d3);
  }
  const pg = new THREE.BufferGeometry();
  pg.setAttribute('position', new THREE.Float32BufferAttribute(projVerts, 3));
  pg.setIndex(projIdx);
  const pm = new THREE.Mesh(pg, new THREE.MeshBasicMaterial({ color: BLUE, transparent: true, opacity: 0.45, side: THREE.DoubleSide, depthWrite: false }));
  pm.renderOrder = 3;
  dynamicGroup.add(pm);
  for (const rad of [rr0, rr1]) addEdgeCurve(dynamicGroup, curvePts(u => M(rad * Math.cos(theta0 + dt * u), rad * Math.sin(theta0 + dt * u), 0), 26), BLUE_EDGE);
  for (const th of [theta0, t1]) addEdgeCurve(dynamicGroup, [M(rr0 * Math.cos(th), rr0 * Math.sin(th), 0), M(rr1 * Math.cos(th), rr1 * Math.sin(th), 0)], BLUE_EDGE);

  for (const r of [rho0, r1]) for (const p of [phi0, p1]) for (const t of [theta0, t1]) {
    const top = sph(r, p, t);
    const rad = r * Math.sin(p);
    const bot = M(rad * Math.cos(t), rad * Math.sin(t), 0);
    dynamicGroup.add(lineObj([top, bot], GREY, true, 0.65));
  }

  const thMid = theta0 + dt / 2;
  const dimA = M(0, 0, -0.12);
  const dimB = M((rho0 * Math.sin(phi0)) * Math.cos(thMid), (rho0 * Math.sin(phi0)) * Math.sin(thMid), -0.12);
  dynamicGroup.add(lineObj([dimA, dimB], 0x000000));
  const tickDir = M(Math.cos(thMid + Math.PI / 2), Math.sin(thMid + Math.PI / 2), 0).multiplyScalar(0.08);
  dynamicGroup.add(lineObj([dimA.clone().sub(tickDir), dimA.clone().add(tickDir)], 0x000000));
  dynamicGroup.add(lineObj([dimB.clone().sub(tickDir), dimB.clone().add(tickDir)], 0x000000));
  addArrowLine(dynamicGroup, M(rr1 * Math.cos(t1) + 0.70, rr1 * Math.sin(t1) - 0.16, 0.34), M(rr1 * Math.cos(t1), rr1 * Math.sin(t1), 0.03), 0x000000, 0.035, 0.12);

  updateTube(hCellR, curvePts(u => sph(rho0 + dr * u, p1, t1), 24), activeKey === 'rho' ? 0.045 : 0.032);
  updateTube(hCellP, curvePts(u => sph(r1, phi0 + dp * u, theta0), 30), activeKey === 'phi' ? 0.045 : 0.032);
  updateTube(hCellT, curvePts(u => sph(r1, p1, theta0 + dt * u), 30), activeKey === 'theta' ? 0.045 : 0.032);

  buildSweepArrow(dr, dp, dt);

  const ins = insetCorners(dr, dp, dt);
  const co = ins.corners;
  dynamicGroup.add(faceMeshFromCorners(co, [
    [cidx(0,0,0), cidx(0,0,1), cidx(0,1,1), cidx(0,1,0)],
    [cidx(1,0,0), cidx(1,1,0), cidx(1,1,1), cidx(1,0,1)],
    [cidx(0,1,0), cidx(0,1,1), cidx(1,1,1), cidx(1,1,0)],
    [cidx(0,0,1), cidx(1,0,1), cidx(1,1,1), cidx(0,1,1)]
  ], ORANGE, 0.38));
  const segPts = [];
  for (let i = 0; i < 2; i++) for (let j = 0; j < 2; j++) segPts.push(co[cidx(i,j,0)], co[cidx(i,j,1)]);
  for (let i = 0; i < 2; i++) for (let k = 0; k < 2; k++) segPts.push(co[cidx(i,0,k)], co[cidx(i,1,k)]);
  for (let j = 0; j < 2; j++) for (let k = 0; k < 2; k++) segPts.push(co[cidx(0,j,k)], co[cidx(1,j,k)]);
  dynamicGroup.add(lineSegmentsObj(segPts, ORANGE_EDGE));

  updateTube(hInsetR, [co[cidx(0,1,1)], co[cidx(1,1,1)]], activeKey === 'rho' ? 0.052 : 0.038);
  updateTube(hInsetP, [co[cidx(1,0,1)], co[cidx(1,1,1)]], activeKey === 'phi' ? 0.052 : 0.038);
  updateTube(hInsetT, [co[cidx(1,1,0)], co[cidx(1,1,1)]], activeKey === 'theta' ? 0.052 : 0.038);

  const rhoAnchor = co[cidx(0,1,1)].clone().add(new THREE.Vector3(-0.56, 0.36, 0.04));
  const phiAnchor = co[cidx(1,0,1)].clone().add(new THREE.Vector3(-0.42, 0.50, -0.16));
  const thetaAnchor = co[cidx(1,1,1)].clone().add(new THREE.Vector3(0.48, 0.76, 0.04));
  addArrowLine(insetLeaderGroup, rhoAnchor, co[cidx(0,1,1)].clone().lerp(co[cidx(1,1,1)], 0.42), 0x000000, 0.03, 0.11);
  addArrowLine(insetLeaderGroup, phiAnchor, co[cidx(1,0,1)].clone().lerp(co[cidx(1,1,1)], 0.58), 0x000000, 0.03, 0.11);
  addArrowLine(insetLeaderGroup, thetaAnchor, co[cidx(1,1,0)].clone().lerp(co[cidx(1,1,1)], 0.65), 0x000000, 0.03, 0.11);

  if (labelRefs.dphi) labelRefs.dphi.pos.copy(sph(0.78, phi0 + dp * 0.42, theta0).add(new THREE.Vector3(-0.04, 0.04, 0.02)));
  if (labelRefs.dtheta) labelRefs.dtheta.pos.copy(M(0.74 * Math.cos(theta0 * 0.50), 0.74 * Math.sin(theta0 * 0.50), 0).add(new THREE.Vector3(0, -0.04, 0)));
  if (labelRefs.drhoAxis) labelRefs.drhoAxis.pos.copy(M(bx - 0.18, 0, (z0 + z2) / 2));
  if (labelRefs.rsinphi) labelRefs.rsinphi.pos.copy(dimA.clone().lerp(dimB, 0.54).add(new THREE.Vector3(0.02, -0.16, 0)));
  if (labelRefs.rsinphidthetaCoord) labelRefs.rsinphidthetaCoord.pos.copy(M(rr1 * Math.cos(t1) + 0.68, rr1 * Math.sin(t1) - 0.22, 0.34));
  if (labelRefs.coordDr) labelRefs.coordDr.pos.copy(sph(rho0 + dr * 0.55, p1, t1).add(new THREE.Vector3(-0.08, 0.12, 0.03)));
  if (labelRefs.coordRp) labelRefs.coordRp.pos.copy(sph(r1, phi0 + dp * 0.55, theta0).add(new THREE.Vector3(0.02, 0.12, -0.04)));
  if (labelRefs.coordRt) labelRefs.coordRt.pos.copy(sph(r1, p1, theta0 + dt * 0.55).add(new THREE.Vector3(0.12, 0.05, 0.03)));

  if (labelRefs.inDr) labelRefs.inDr.pos.copy(rhoAnchor.clone().add(new THREE.Vector3(-0.08, 0.12, 0)));
  if (labelRefs.inRp) labelRefs.inRp.pos.copy(phiAnchor.clone().add(new THREE.Vector3(-0.02, 0.10, 0)));
  if (labelRefs.inRt) labelRefs.inRt.pos.copy(thetaAnchor.clone().add(new THREE.Vector3(0.04, 0.12, 0)));
  if (formulaLabel) formulaLabel.pos.copy(ins.center.clone().add(new THREE.Vector3(0.05, -1.10, -0.08)));

  setEdgeEmphasis();
  updateLabelsVisibility();
}

