  if (labelRefs.coordRp) labelRefs.coordRp.pos.copy(sph(r1, phi0 + dp * 0.53, theta0).add(new THREE.Vector3(0.22, 0.28, -0.03)));
  if (labelRefs.coordRt) labelRefs.coordRt.pos.copy(sph(r1, p1, theta0 + dt * 0.55).add(new THREE.Vector3(0.32, 0.18, 0.03)));

  if (labelRefs.inDr) labelRefs.inDr.pos.copy(rhoAnchor.clone().add(new THREE.Vector3(-0.07, 0.12, 0)));
