  }
];

let tweenId = 0;
window.goToStep = function goToStep(i) {
  const step = demoSteps[i] || demoSteps[0];
  const start = {
    deltaRho: parseFloat(document.getElementById('deltaRho').value),
    deltaPhi: parseFloat(document.getElementById('deltaPhi').value),
    deltaTheta: parseFloat(document.getElementById('deltaTheta').value)
  };
  const end = step.state;
  document.getElementById('labelOverlay').value = end.labelOverlay;
  document.getElementById('stepText').innerHTML = '<b>' + step.title + '</b><br>' + step.narration;
  const my = ++tweenId;
  const t0 = performance.now();
  function frame(now) {
    if (my !== tweenId) return;
    const u0 = Math.min(1, (now - t0) / 650);
    const u = u0 * u0 * (3 - 2 * u0);
    for (const k of ['deltaRho', 'deltaPhi', 'deltaTheta']) {
      document.getElementById(k).value = (start[k] + (end[k] - start[k]) * u).toFixed(3);
    }
    updateFigure();
    if (u0 < 1) requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
};

for (let i = 0; i < 4; i++) {
  document.getElementById('step' + i).addEventListener('click', () => window.goToStep(i));
